h1 {
  font-family: 'Inter var', sans-serif; /* Assumes a variable font is loaded */
  font-variation-settings: "wght" 700, "wdth" 100;
  transition: font-variation-settings 0.3s ease-in-out;
}

h1:hover {
  font-variation-settings: "wght" 900, "wdth" 120;
}

/* For custom axes, check font documentation, e.g., 'GRAD' for grade */
p.subtle-text {
  font-family: 'MyCustomVarFont', sans-serif;
  font-variation-settings: "wght" 400, "GRAD" 50; /* Example with custom axis 'GRAD' */
}
